DROP TABLE IF EXISTS `daily_summaries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily_summaries` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `station_id` bigint unsigned NOT NULL,
  `obs_time_utc` datetime NOT NULL,
  `obs_time_local` datetime NOT NULL,
  `solar_radiation_high` decimal(8,2) DEFAULT NULL,
  `uv_high` decimal(4,2) DEFAULT NULL,
  `winddir_avg` smallint DEFAULT NULL,
  `humidity_high` tinyint DEFAULT NULL,
  `humidity_low` tinyint DEFAULT NULL,
  `humidity_avg` tinyint DEFAULT NULL,
  `temp_high` decimal(5,2) DEFAULT NULL,
  `temp_low` decimal(5,2) DEFAULT NULL,
  `temp_avg` decimal(5,2) DEFAULT NULL,
  `windspeed_high` decimal(5,2) DEFAULT NULL,
  `windspeed_low` decimal(5,2) DEFAULT NULL,
  `windspeed_avg` decimal(5,2) DEFAULT NULL,
  `windgust_high` decimal(5,2) DEFAULT NULL,
  `windgust_low` decimal(5,2) DEFAULT NULL,
  `windgust_avg` decimal(5,2) DEFAULT NULL,
  `dewpt_high` decimal(5,2) DEFAULT NULL,
  `dewpt_low` decimal(5,2) DEFAULT NULL,
  `dewpt_avg` decimal(5,2) DEFAULT NULL,
  `windchill_high` decimal(5,2) DEFAULT NULL,
  `windchill_low` decimal(5,2) DEFAULT NULL,
  `windchill_avg` decimal(5,2) DEFAULT NULL,
  `heatindex_high` decimal(5,2) DEFAULT NULL,
  `heatindex_low` decimal(5,2) DEFAULT NULL,
  `heatindex_avg` decimal(5,2) DEFAULT NULL,
  `pressure_max` decimal(6,2) DEFAULT NULL,
  `pressure_min` decimal(6,2) DEFAULT NULL,
  `pressure_trend` decimal(6,2) DEFAULT NULL,
  `precip_rate` decimal(6,2) DEFAULT NULL,
  `precip_total` decimal(6,2) DEFAULT NULL,
  `qc_status` smallint DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `daily_summaries_station_id_foreign` (`station_id`),
  CONSTRAINT `daily_summaries_station_id_foreign` FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=709 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
